INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#1','mobile-suit-gundam-wing',1,'The Shooting Star She Saw','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2109/original.jpg','In an effort to end many years of tyrannical rule, five pilots and their Gundams are dispatched to Earth to begin Operation Meteor. Four land without incident, but one is intercepted and his mission is compromised.','[]','1995-04-07','2109');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#2','mobile-suit-gundam-wing',2,'The Gundam Deathscythe','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2110/original.jpg','Heero plans to destroy the Wing Gundam before it is discovered by the Alliance forces. Heero gets his hands on two torpedoes and attempts to destroy his Gundam. Relena, refusing to believe Heero''s threat, tries to confront him but is interrupted by the arrival of Duo Maxwell...','[]','1995-04-14','2110');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#3','mobile-suit-gundam-wing',3,'5 Gundams Confirmed','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2111/original.jpg','Heero is injured and is kept for treatment at the Alliance hospital. At the Corsican base of the Mediterranean, the Gundam Heavyarms, piloted by L3''s Trowa Barton, annihilates everything in its path. Then things get even worse for the Alliance when the Gundam Sandrock shows up.','[]','1995-04-21','2111');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#4','mobile-suit-gundam-wing',4,'The Victoria Nightmare','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2112/original.jpg','L5''s Wufei Chang, in his Shenlong Gundam, attacks the Taurus MS''s transports after coming into Lake Victoria base late at night. Lucrezia Noin, head instructor at the base and good friend of Zechs Merquise, tries to fight him off in her Aries MS.','[]','1995-04-28','2112');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#5','mobile-suit-gundam-wing',5,'Relena’s Secret','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2113/original.jpg','Relena and her father, Vice Foreign Minister Darlian, journey to the colonies to try and prevent war. but there are those who do not want peace. Amidst the grief and tragedy, Relena learns her true identity...','[]','1995-05-05','2113');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#6','mobile-suit-gundam-wing',6,'Party Night','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2114/original.jpg','Relena goes back to Earth. Wufei attacks another Alliance base and Trowa has started to work in a circus as a cover. Back at school, Relena tells Heero that she knows everything about him and invites him to a party, to be held that night.','[]','1995-05-12','2114');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#7','mobile-suit-gundam-wing',7,'Scenario for Bloodshed','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2115/original.jpg','Treize Kushrenada''s plans to destroy the Alliance come to a head when the leaders of the Alliance hold a meeting. The meeting is led by Marshal Noventa and outlines his peace agenda. However, based on Treize''s false intelligence, the Gundams destroy the Alliance leadership, and Oz begins to take over Earth.','[]','1995-05-19','2115');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#8','mobile-suit-gundam-wing',8,'The Treize Assassination','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2116/original.jpg','Lady Une makes the Gundams her next target and activates the self-destruct sequence on the New Edwards Base. Can Heero prevent the explosion of the New Edwards Base and find the person who set them up? Meanwhile, Wufei duels with Treize.','[]','1995-05-26','2116');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#9','mobile-suit-gundam-wing',9,'Portrait of a Ruined Country','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2117/original.jpg','The United Earth Sphere Alliance collapses, sending the entire Planet into a panic. This allows OZ to step forward and take control through a well planned coup. Zechs is occupied with other things: he is searching for the ruins of the Sanc Kingdom.','[]','1995-06-02','2117');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#10','mobile-suit-gundam-wing',10,'Heero, Distracted by Defeat','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2118/original.jpg','Lady Une briefs her troops on another strategy to try and wipe out the Gundams. Heero and Zechs face each other again, but this time it''s the Wing Gundam versus the Tallgeese.','[]','1995-06-09','2118');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#11','mobile-suit-gundam-wing',11,'The Whereabouts of Happiness','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2119/original.jpg','The Gundams have been defeated. With the colonies used as shields, the pilots don''t have a chance. No one knows whether Heero is dead or alive. On the trail of her father''s killer, Relena heads to Moscow. Duo and Quatre take refuge with the Maguanac Corps.','[]','1995-06-16','2119');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#12','mobile-suit-gundam-wing',12,'Bewildered Warriors','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2120/original.jpg','The Gundams must fight to regain peace. Wufei meets Sally Po on the battlefield and tells her that the weak should not be fighting. Still, lost in his emotion, Wufei once again gets into his Shenlong Gundam.','[]','1995-06-23','2120');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#13','mobile-suit-gundam-wing',13,'Catherine’s Tears','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2121/original.jpg','Two misguided OZ soldiers are going on an execution spree, destroying any remaining Alliance resistance. In an effort to save the colonies, Trowa heads for his final battle. However, Catherine stands between him and his death wish...','[]','1995-06-30','2121');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#14','mobile-suit-gundam-wing',14,'The Order to Destroy 01','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2122/original.jpg','To try and make up for his mistake of killing the honorable pacifist leader Noventa, Heero confronts his granddaughter, Sylvia Noventa. Meanwhile, Zechs is handed an order from the Romefeller Foundation...','[]','1995-07-07','2122');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#15','mobile-suit-gundam-wing',15,'To the Battleground, Antarctica','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2123/original.jpg','Zechs'' warrior nature craves a decisive battle. Noin invites Heero to Antarctica, where Zechs awaits. Suspecting that Zechs has violated the order to destroy Zero One, the Romefeller Foundation sends troops after him.','[]','1995-07-14','2123');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#16','mobile-suit-gundam-wing',16,'The Sorrowful Battle','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2124/original.jpg','At the South Pole, Zechs waits with the newly-rebuilt Wing Gundam. After Herro arrives and the rematch begins, Relena arrives and tries to stop them from wasting their lives. However, she discovers a revelation...','[]','1995-07-21','2124');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#17','mobile-suit-gundam-wing',17,'Betrayed by Home, Far Away','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2125/original.jpg','OZ sets in motion its plans to destroy the Alliance military once and for all. Quatre and Duo head to outer space to warn the colonies of the impending danger, only to discover they''ve been declared the enemy.','[]','1995-07-28','2125');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#18','mobile-suit-gundam-wing',18,'Tallgeese Destroyed','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2126/original.jpg','The fight between the Tallgeese and the Gundams conclude. Now, Zechs refuses to fight for, and ends his affiliation with the Romefeller Foundation.','[]','1995-08-04','2126');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#19','mobile-suit-gundam-wing',19,'Assault on Barge','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2127/original.jpg','The Gundam Deathscythe single-handedly battles OZ''s Mobile Suits in space, and Duo ends up getting captured. Heero searches for Duo in order to silence him...','[]','1995-08-11','2127');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#20','mobile-suit-gundam-wing',20,'The Lunar Base Infiltration','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2128/original.jpg','OZ is developing 2 new Mobile Suits that can challenge the Gundams. Heero accepts the mission to sneak in and sabotage their operations. But he is unprepared for who he meets while inside the base...','[]','1995-08-18','2128');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#21','mobile-suit-gundam-wing',21,'Grief Stricken Quatre','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2129/original.jpg','A wild Mobile Suit approaches the colonies at high speed; Lady Une orders test pilots Heero and Trowa to stop it. Meanwhile, Quatre, exhausted from the pressure of his missions, returns home for a visit. But what he finds there is not comfort, only more chaos and tragedy.','[]','1995-08-25','2129');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#22','mobile-suit-gundam-wing',22,'The Fight for Independence','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2130/original.jpg','The colonies have begun arming themselves for the coming fight against OZ. However, more surprising than that is the switch in Lady Une-she''s become an advocate for peace. She is now acting on Treize''s behalf without the consent of the Romefeller Foundation.','[]','1995-08-31','2130');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#23','mobile-suit-gundam-wing',23,'Duo, God of Death Once Again','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2131/original.jpg','With Lady Une''s help, Duo escapes from OZ and goes to destroy the Mobile Suit production base on the moon. But while there, he meets a girl named Hilde who has become a soldier. The choice is suddenly much more complicated.','[]','1995-09-01','2131');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#24','mobile-suit-gundam-wing',24,'The Gundam They Called Zero','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2132/original.jpg','A Mobile Suit with fantastic power is on a rampage. It''s attacking the colonies one after another in a brutal display of raw power. Trowa and Heero move to intercept this strange new Mobile Suit and are surprised by who its pilot is...','[]','1995-09-08','2132');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#25','mobile-suit-gundam-wing',25,'Quatre vs. Heero','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2133/original.jpg','Trowa and Heero must battle their crazed friend; but they find themselves losing against this new Gundam. Treize, meanwhile, disapproves of the Romefeller Foundation''s plan to use Mobile Dolls-automated Mobile Suits without pilots. His dissension results in his arrest by OZ.','[]','1995-09-22','2133');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#26','mobile-suit-gundam-wing',26,'The Eternal Flame of the Shooting Stars','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2134/original.jpg','Treize is freed by OZ soldiers loyal to him, but the trouble is only beginning. Romefeller is out to eliminate the Gundams and Treize, since they are symbols of hipe. Operation NOVA commences, and all of the Earth is in danger.','[]','1995-09-29','2134');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#27','mobile-suit-gundam-wing',27,'The Locus of Victory and Defeat','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2135/original.jpg','This episode is just a very lengthy flashback of all the major things that happened to Relena throughout the series - with particular emphasis on Heero and Zechs. The episode ends with Relena yelling out of an open window for Heero to return to her and end the war.','[]','1995-10-06','2135');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#28','mobile-suit-gundam-wing',28,'Passing Destinies','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2136/original.jpg','Another flashback episode! This one is reflected on by Treize and focuses mainly on the progression of OZ. It ends with a very interesting scene. Treize is on a computer analyzing/working on the Epyon. A woman with a rose comes to him from behind - could it be Lady Une? Also interesting, on Treize''s computer there are two pictures of Lady Une next to a rose - one of each version of her.','[]','1995-10-13','2136');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#29','mobile-suit-gundam-wing',29,'The Heroine of the Battlefield','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2137/original.jpg','Romefeller is gaining ground on Earth very quickly and Treize and his troops seem to be losing the battle. When Heero realizes that Treize is now fighting Romefeller, he joins his army as a mercenary and finds himself working alongside Sally Po and Lucrezia Noin.','[]','1995-10-20','2137');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#30','mobile-suit-gundam-wing',30,'The Reunion With Relena','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2138/original.jpg','Quatre isn''t convinced that Heero''s mercenary path is the correct one. However, having witnessed the horrors of war, he cannot stand by and do nothing. When Relena declares the Sanc Kingdom''s neutrality, Quatre and Heero take refuge.','[]','1995-10-27','2138');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#31','mobile-suit-gundam-wing',31,'The Glass Kingdom','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2139/original.jpg','Heero and Quatre decide to stay in the Sanc Kingdom and help Relena promote pacifism. But when the Romefeller Foundation attacks, Heero, Quatre and Noin go into battle.','[]','1995-11-03','2139');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#32','mobile-suit-gundam-wing',32,'The God of Death Meets Zero','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2140/original.jpg','Still in space, Duo has been retaliating against OZ. But OZ closes in, and Duo and his incomplete Gundam Deathscythe Hell must fight the Wing Zero.','[]','1995-11-17','2140');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#33','mobile-suit-gundam-wing',33,'The Lonely Battlefield','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2141/original.jpg','Zechs steps onto the battlefield once again and attacks Romefeller''s forces. Meanwhile, Heero heads off to help the Treize Faction.','[]','1995-11-24','2141');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#34','mobile-suit-gundam-wing',34,'And It’s Name is Epyon','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2142/original.jpg','Zechs gets the Wing Gundam Zero and demolishes the OZ forces. However, Treize gives Heero a new Gundam, perhaps the most terrible Gundam of all, and its name is Epyon...','[]','1995-12-01','2142');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#35','mobile-suit-gundam-wing',35,'The Return of Wu Fei','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2143/original.jpg','Wanting to join the Gundam pilots in their fight, Zechs goes to meet Wufei, But Wufei, pilot of the new Altron Gundam, believes him to be the enemy.','[]','1995-12-08','2143');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#36','mobile-suit-gundam-wing',36,'Sanc Kingdom’s Collapse','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2144/original.jpg','Duo and Trowa are reunited and team up against the enemy once more. Meanwhile, the Romefeller Foundation has mounted a final assault against the Sanc Kingdom, forcing Relena to surrender to prevent a battle.','[]','1995-12-15','2144');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#37','mobile-suit-gundam-wing',37,'Zero vs. Epyon','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2145/original.jpg','Relena, now a prisoner of the Romefeller Foundation, is faced with a very difficult choice. Meanwhile Heero and Zechs engage in battle once again-this time on the grounds of the Sanc Kingdom.','[]','1995-12-22','2145');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#38','mobile-suit-gundam-wing',38,'The Birth of Queen Relena','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2146/original.jpg','A group of rebel colony citizens calling themselves the "White Fang" starts attacking OZ bases. Quatre and Noin search for the other Gundam pilots. The Romefeller Foundation names Queen Relena as their representative.','[]','1996-01-12','2146');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#39','mobile-suit-gundam-wing',39,'Trowa’s Return to the Battlefield','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2147/original.jpg','Quinze, the leader of the White Fang, contacts Zechs and asks him-and his Gundam-to join their cause. Still suffering from amnesia, Trowa once agian goes into battle.','[]','1996-01-19','2147');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#40','mobile-suit-gundam-wing',40,'A New Leader','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2148/original.jpg','As Relena takes her first step towards trying to achieve true peace, Heero sets out to eliminate her. Milliardo Peacecraft, the new leader of the White Fang, is now intent on going to war against OZ, the Romefeller Foundation and the Gundam pilots.','[]','1996-01-26','2148');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#41','mobile-suit-gundam-wing',41,'Crossfire at Barge','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2149/original.jpg','With Milliardo Peacecraft''s declaration of war against the Earth in effect, the battle rages on between the White Fang and OZ. Meanwhile, Treize returns to take control of the Romefeller Foundation, forcing Relena to step down. In space, the Gundam pilots encounter Milliardo and his Epyon.','[]','1996-02-02','2149');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#42','mobile-suit-gundam-wing',42,'Battleship Libra','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2150/original.jpg','The survivors of the destruction of Barge are brought to Earth, one of them being Lady Une. Treize reveals his true intentions. As the battle continues, Relena heads for Libra.','[]','1996-02-09','2150');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#43','mobile-suit-gundam-wing',43,'Target: Earth','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2151/original.jpg','The Gundam pilots reunite. OZ takes control of a colony demanding the White Fang surrender Libra. When Trowa learns that Catherine is in the colony, he leaps to action. Meanwhile, Relena struggles to talk some sense into her brother.','[]','1996-02-16','2151');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#44','mobile-suit-gundam-wing',44,'Go Forth, Gundam Team','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2152/original.jpg','Relena''s plead for her brother to stop the war goes unheeded. The Gundam pilots battle their way though a fierce encounter with Mobile Dolls under Dorothy''s control.','[]','1996-02-23','2152');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#45','mobile-suit-gundam-wing',45,'Signs of the Final Battle','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2153/original.jpg','Milliardo leaves Quinze in command temporarily as he takes a rest. The Mercurius and Vayeate are once again used against the Gundams. However, this proves to be the two Mobile Suits'' last battle.','[]','1996-03-01','2153');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#46','mobile-suit-gundam-wing',46,'Milliardo’s Decision','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2154/original.jpg','Heero manages to get into the Libra and reunites with Relena to confront Milliardo. Treize challenges Milliardo with his new Tallgeese II Mobile Suit. To try and eliminate Treize, he fires the Libra...','[]','1996-03-08','2154');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#47','mobile-suit-gundam-wing',47,'Collision in Space','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2155/original.jpg','The five Gundams launch their ultimate offensive knowing that only mass slaughter and a sad battlefield awaits them. The Peacemillion space fortress rams the Libra to block White Fang''s way to Earth, even if it will bring their own death.','[]','1996-03-15','2155');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#48','mobile-suit-gundam-wing',48,'Takeoff into Confusion','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2156/original.jpg','While Wufei fights Treize, Quatre fights Dorothy, Trowa tries to change his destiny, Duo frees the scientists, and Heero looks for Milliardo for the last round of their duel.','[]','1996-03-22','2156');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('mobile-suit-gundam-wing#49','mobile-suit-gundam-wing',49,'The Final Victor','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/2157/original.jpg','As Heero and Zechs come to the end of their final duel, the battleship Libra and Peacemillion descend upon the earth threatening to engulf the world in a never ending winter.... Meanwhile Trowa helps out the wounded Quatre, and Duo delivers the "lords of plague" to peacemillion, in the hopes of averting the tradgedy of the battleships plunge.','[]','1996-03-29','2157');

